import { test, expect } from '@playwright/test';

test.describe('401 Error Handling - Redirect to Login', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should redirect to login page when API returns 401 Unauthorized', async ({ page }) => {
    // Set up intercept for unauthorized response
    await page.route('**/api/data', (route) => {
      route.abort('failed');
    });

    // Attempt to access protected route
    const dashboardButton = page.getByRole('button', { name: /dashboard/i });
    await dashboardButton.click();

    // Verify redirection to login
    const loginPage = page.getByRole('dialog', { name: /login/i });
    await expect(loginPage).toBeVisible();

    // Verify login button is visible
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/unauthorized/i);
    await expect(errorMessage).toBeVisible();

    // Verify user is not logged in
    const userProfile = page.getByText(/user profile/i);
    await expect(userProfile).not.toBeVisible();
  });

  test('should handle 401 error with custom error page', async ({ page }) => {
    // Set up intercept for unauthorized response
    await page.route('**/api/data', (route) => {
      route.abort('failed');
    });

    // Set up intercept for custom error page
    await page.route('**/api/error', (route) => {
      route.abort('failed');
    });

    // Attempt to access protected route
    const dashboardButton = page.getByRole('button', { name: /dashboard/i });
    await dashboardButton.click();

    // Verify custom error page is displayed
    const errorPage = page.getByRole('dialog', { name: /error/i });
    await expect(errorPage).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/unauthorized/i);
    await expect(errorMessage).toBeVisible();

    // Verify user is not logged in
    const userProfile = page.getByText(/user profile/i);
    await expect(userProfile).not.toBeVisible();

    // Verify login button is visible
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeVisible();
  });
});
